import { cn } from '@/lib/utils'
import { useTheme } from '@/themes'

const assetPath = (path: string) => `${import.meta.env.BASE_URL}${path.replace(/^\/+/, '')}`

// Brand badge: the Scout mark (a speech bubble holding a north star) on the
// app-icon tile, theme-aware — iMessage-blue tile in light mode, deep navy in
// dark. The PNG carries the rounded shape and transparent corners, so no
// tile/rounding classes here. Generated by scripts/generate_icons.py from
// assets/scout-mark.svg; size via className (default size-14).
export function BrandMark({ className, ...props }: React.ComponentProps<'span'>) {
  const { renderedMode } = useTheme()
  const dark = renderedMode === 'dark'

  return (
    <span className={cn('inline-flex size-14 shrink-0 items-center justify-center', className)} {...props}>
      <img alt="" className="size-full object-contain" src={assetPath(dark ? 'scout-mark-dark.png' : 'scout-mark.png')} />
    </span>
  )
}
